def extract_phase_values(problems: List[dict], phase: str):
    vals, pids = [], []
    for p in problems:
        v = p.get(f"ii_{phase}")
        if v is not None:
            vals.append(v)
            pids.append(p["problem_id"])
    return np.array(vals), pids


def compute_phase_gradient(problems: List[dict]):
    """D = ii_low - ii_high per problem."""
    diffs, pids = [], []
    for p in problems:
        lo, hi = p.get("ii_low"), p.get("ii_high")
        if lo is not None and hi is not None:
            diffs.append(lo - hi)
            pids.append(p["problem_id"])
    return np.array(diffs), pids


def bootstrap_ci_median(values: np.ndarray, B: int = B_BOOTSTRAP,
                        alpha: float = ALPHA, seed: int = SEED):
    rng = np.random.RandomState(seed)
    n = len(values)
    boot = np.array([
        np.median(values[rng.randint(0, n, size=n)]) for _ in range(B)
    ])
    lo = float(np.percentile(boot, 100 * alpha / 2))
    hi = float(np.percentile(boot, 100 * (1 - alpha / 2)))
    return lo, hi


def paired_cohens_dz(diffs: np.ndarray) -> float:
    if len(diffs) < 2:
        return float("nan")
    s = np.std(diffs, ddof=1)
    if s == 0:
        return float("nan")
    return float(np.mean(diffs) / s)


def wilcoxon_test(diffs: np.ndarray):
    nonzero = diffs[diffs != 0]
    if len(nonzero) < 10:
        return float("nan"), float("nan")
    stat, p = stats.wilcoxon(nonzero)
    return float(stat), float(p)


def interpret_d(d: float) -> str:
    ad = abs(d)
    if np.isnan(ad):
        return "nan"
    if ad < 0.2:
        return "negligible"
    if ad < 0.5:
        return "small"
    if ad < 0.8:
        return "medium"
    return "large"


