        if len(vals) < 10:
            result[f"phase_{phase}"] = {"error": f"too few ({len(vals)})"}
            continue
        med = float(np.median(vals))
        ci_lo, ci_hi = bootstrap_ci_median(vals)
        result[f"phase_{phase}"] = {
            "n": len(vals),
            "median_II": med,
